('06a7fb53-9552-5d90-8cd5-0d6a9978ae34'::uuid,'FIN-F04','Special Trust Fund ageing ledger entry','Chapter 5 FIN-F04 (SOP 5-03). One entry per year of origin.','d7190e43-31f8-55d7-b646-04574073dedf'::uuid,'{"fields": [{"key": "year_of_origin", "label": "Year of origin", "type": "integer", "required": true, "min": 2010}, {"key": "amount_php", "label": "Amount accrued (PHP)", "type": "number", "required": true, "min": 0}, {"key": "used_php", "label": "Used to date (PHP)", "type": "number", "required": true, "min": 0}, {"key": "deadline_year", "label": "Last year of use (origin + 5)", "type": "integer", "required": true}, {"key": "programmed_use", "label": "Programmed use and approving resolution", "type": "textarea", "required": false}, {"key": "aa_available", "label": "Listed as an AA source", "type": "checkbox", "required": false}]}'::jsonb,'draft',1),
('821af167-6f51-5d36-a745-297a1ae1076b'::uuid,'FIN-F05','QRF use request and certification','Chapter 5 FIN-F05 (SOP 5-04). No QRF without a State of Calamity.','d7190e43-31f8-55d7-b646-04574073dedf'::uuid,'{"fields": [{"key": "soc_ref", "label": "State of Calamity (SP resolution, date, area)", "type": "text", "required": true}, {"key": "purpose", "label": "Purpose", "type": "select", "required": true, "options": ["Relief", "Recovery"]}, {"key": "items", "label": "Items and quantities", "type": "textarea", "required": true}, {"key": "amount_php", "label": "Amount (PHP)", "type": "number", "required": true, "min": 0}, {"key": "procurement_mode", "label": "Procurement mode", "type": "select", "required": true, "options": ["Stock or framework agreement", "Emergency procurement (FIN-F07)", "Other mode"]}, {"key": "certifications", "label": "Budget and Accounting certifications obtained", "type": "checkbox", "required": true}, {"key": "qrf_balance_php", "label": "QRF balance after this request (PHP)", "type": "number", "required": false, "min": 0}]}'::jsonb,'draft',1),
('719aaf67-26f5-5f18-bb0e-b427ab802f38'::uuid,'FIN-F06','Anticipatory action fund release and tranche record','Chapter 5 FIN-F06 (SOP 5-05); RA 12287 IRR Rule V. Feeds the 45-day report.','d7190e43-31f8-55d7-b646-04574073dedf'::uuid,'{"fields": [{"key": "sid_ref", "label": "State of Imminent Disaster (Mayor''s EO, date)", "type": "text", "required": true}, {"key": "hazard_family", "label": "Hazard family", "type": "select", "required": true, "options": ["Hydrometeorological", "Geological", "Slow-onset (e.g., drought)", "Other"]}, {"key": "impact_time", "label": "Forecast impact time", "type": "datetime", "required": true}, {"key": "aa_allocation_php", "label": "AA allocation for the year (PHP)", "type": "number", "required": true, "min": 0}, {"key": "source", "label": "Fund source", "type": "select", "required": true, "options": ["70% component (LDRRMFIP line)", "AA line (within the 70%)", "QRF (30%)", "Special Trust Fund", "Donation or grant", "Other lawful source"]}, {"key": "measure", "label": "AA measure and lead office", "type": "textarea", "required": true}, {"key": "amount_php", "label": "Amount released (PHP)", "type": "number", "required": true, "min": 0}, {"key": "timing", "label": "Intervention timing", "type": "select", "required": true, "options": ["More than 3 days before impact (cap 30%)", "Within 3 days of impact (up to 70%)", "Not graduated (other source or slow-onset)"]}, {"key": "within_cap", "label": "Within the tranche rule after this release", "type": "checkbox", "required": true}, {"key": "closure", "label": "On lifting: spent, unused to STF", "type": "textarea", "required": false}]}'::jsonb,'draft',1),
('c6a4ec41-e380-51cf-9870-7d17debcb304'::uuid,'FIN-F07','Emergency procurement justification and record','Chapter 5 FIN-F07 (SOP 5-07); RA 12009 Sec. 35(b). Completed before the purchase.','d7190e43-31f8-55d7-b646-04574073dedf'::uuid,'{"fields": [{"key": "ground", "label": "Ground", "type": "select", "required": true, "options": ["Imminent danger to life or property during a State of Calamity", "Time is of the essence because of a calamity"]}, {"key": "ground_detail", "label": "Facts showing the ground (declaration reference or calamity, why immediate action is needed)", "type": "textarea", "required": true}, {"key": "items", "label": "Item, quantity and use", "type": "textarea", "required": true}, {"key": "charging", "label": "Charging", "type": "select", "required": true, "options": ["70% component (LDRRMFIP line)", "AA line (within the 70%)", "QRF (30%)", "Special Trust Fund", "Donation or grant", "Other lawful source"]}, {"key": "amount_php", "label": "Amount (PHP)", "type": "number", "required": true, "min": 0}, {"key": "supplier", "label": "Supplier (business name)", "type": "text", "required": true}, {"key": "hope_approval", "label": "HoPE approval reference", "type": "text", "required": true}, {"key": "iar", "label": "Inspection and acceptance report reference", "type": "text", "required": false}, {"key": "posted", "label": "Posted and reported as RA 12009 IRR requires", "type": "checkbox", "required": false}]}'::jsonb,'draft',1),
('9df9d8e0-bbaa-55d1-82dc-27e936e21f12'::uuid,'FIN-F08','Pre-arranged supplier and framework agreement register entry','Chapter 5 FIN-F08 (SOP 5-06).','d7190e43-31f8-55d7-b646-04574073dedf'::uuid,'{"fields": [{"key": "item", "label": "Item or service", "type": "text", "required": true}, {"key": "supplier", "label": "Supplier (business name)", "type": "text", "required": true}, {"key": "agreement", "label": "Agreement type and reference", "type": "select", "required": true, "options": ["Framework agreement", "Supplier list only", "MOA with partner", "Other"]}, {"key": "quantity", "label": "Quantity range and delivery time", "type": "text", "required": true}, {"key": "trigger", "label": "Activation trigger (incl. AA use)", "type": "text", "required": true}, {"key": "valid_until", "label": "Valid until", "type": "date", "required": true}, {"key": "contact", "label": "Contact (position and channel)", "type": "text", "required": true}, {"key": "last_test", "label": "Last call-down test", "type": "date", "required": false}]}'::jsonb,'draft',1),
('36fe0e80-9ae6-507c-a767-b3a196121344'::uuid,'FIN-F09','Donation receipt and acknowledgement','Chapter 5 FIN-F09 (SOP 5-08); SP Res. 2024-102. No beneficiary names.','d7190e43-31f8-55d7-b646-04574073dedf'::uuid,'{"fields": [{"key": "donor_type", "label": "Donor type", "type": "select", "required": true, "options": ["Private individual", "Business", "NGO or CSO", "Other LGU", "National agency", "International partner"]}, {"key": "form", "label": "Form", "type": "select", "required": true, "options": ["Cash", "In kind"]}, {"key": "description", "label": "Description and quantity", "type": "textarea", "required": true}, {"key": "value_php", "label": "Value (PHP)", "type": "number", "required": true, "min": 0}, {"key": "conditions", "label": "Donor conditions", "type": "textarea", "required": false}, {"key": "acceptance_ref", "label": "Acceptance document reference", "type": "text", "required": true}, {"key": "custody", "label": "Custodian office", "type": "select", "required": true, "options": ["City Treasurer", "CGSO", "CSWDO"]}, {"key": "booked", "label": "Recorded by the City Accountant", "type": "checkbox", "required": false}, {"key": "disclosed", "label": "Disclosed", "type": "checkbox", "required": false}]}'::jsonb,'draft',1),
('2f55b820-1001-5ca5-a4c5-b377ee817b0a'::uuid,'FIN-F10','Fund adequacy test','Chapter 5 FIN-F10 (SOP 5-09); UNDRR Scorecard 3.2.3-3.2.4.','d7190e43-31f8-55d7-b646-04574073dedf'::uuid,'{"fields": [{"key": "scenario", "label": "Scenario and contingency plan", "type": "text", "required": true}, {"key": "cost_php", "label": "Cost of response and early recovery (PHP)", "type": "number", "required": true, "min": 0}, {"key": "cost_basis", "label": "Cost basis by item", "type": "textarea", "required": true}, {"key": "available_php", "label": "Available: QRF, AA line, STF, insurance, other (PHP)", "type": "number", "required": true, "min": 0}, {"key": "shortfall_php", "label": "Shortfall (PHP)", "type": "number", "required": false, "min": 0}, {"key": "fallback", "label": "Fallback sources and actions", "type": "textarea", "required": true}]}'::jsonb,'draft',1),
('373ea2c4-34fe-51ec-9954-04d5a4ac630f'::uuid,'FIN-F11','Audit observation and corrective action tracker','Chapter 5 FIN-F11 (SOP 5-10); feeds Chapter 7.','d7190e43-31f8-55d7-b646-04574073dedf'::uuid,'{"fields": [{"key": "reference", "label": "AOM or AAR reference", "type": "text", "required": true}, {"key": "finding", "label": "Finding", "type": "textarea", "required": true}, {"key": "action", "label": "Corrective action", "type": "textarea", "required": true}, {"key": "owner", "label": "Accountable office", "type": "text", "required": true}, {"key": "due", "label": "Due date", "type": "date", "required": true}, {"key": "status", "label": "Status", "type": "select", "required": true, "options": ["Open", "Replied", "Implemented", "Closed by COA", "Not implemented"]}]}'::jsonb,'draft',1)
insert into public.protocol_templates (id,code,title,purpose,trigger_text,document_id,owner_role,category,status,template_rev,kind,sop_ref,process_owner,policy_refs,indicator_ids) values
('55be2771-3236-5a6e-bf1e-5d4e9d2f3a45'::uuid,'PR-DUTY-HANDOVER','Duty shift handover','Keep 24/7 operations continuous between shifts.','Every change of duty shift at the Operations Center.','eafa0947-d859-57e8-b93e-affd8500f0a5'::uuid,'duty_officer'::public.app_role,'daily_operations','draft',1,'protocol','SOP HR-05 (MOO Ch.2, Annex 2-K; checklist Annex 2-E, form HR-F04)','CDRRMO Head / division leads (SOP HR-05); handover done by the duty officer on shift',array['RA 10121 Sec. 12(c)','NDRRMC Memo 131 s. 2018']::text[],array['A2.5','B4.3']::text[]),
('f726b603-075b-5232-a798-5054f4d3e64d'::uuid,'PR-WARNING-DISSEM','Warning dissemination','Move a hazard bulletin to every at-risk purok, in a form people understand.','On receipt of a PAGASA, PHIVOLCS or MGB bulletin or advisory that affects Ormoc.','eafa0947-d859-57e8-b93e-affd8500f0a5'::uuid,'duty_officer'::public.app_role,'warning','draft',1,'protocol','SOP 4-02 (MOO Ch.4 v1.1)','CDRRMO Head / warning and public information focal person; decisions stay with the competent official',array['RA 10121 Sec. 12(c)','DILG VIII Disaster Response Reporting SOP (RDRRMC8 Res. 12-006)']::text[],array['A6.1','A6.2','A6.3','A6.4','B5.6']::text[]),
('fef14daa-970e-5cf1-aa23-ec53b0b5c3b1'::uuid,'PR-EOC-ACTIVATE','EOC activation (Blue or Red)','Stand up the EOC quickly with the right people and records.','When the EOC is raised to Blue or Red as directed by the City Mayor (Responsible Official), or by the EOC Manager under the approved activation protocol.','eafa0947-d859-57e8-b93e-affd8500f0a5'::uuid,'eoc_manager'::public.app_role,'eoc','draft',1,'protocol','SOP 4-04 (MOO Ch.4 v1.1)','Official designated in the EOC EO authorises; EOC Manager implements',array['NDRRMC Memo 131 s. 2018','DILG VIII Disaster Response Reporting SOP (RDRRMC8 Res. 12-006)']::text[],array['B1.2','B1.3','B4.1','B4.2']::text[]),
('c79bca15-67f0-538e-9e52-8d969da30076'::uuid,'PR-PDRA','Pre-disaster risk assessment (PDRA)','Decide, from the forecast and local exposure, whether to monitor, act early or request a declaration.','When a forecast hazard may affect Ormoc.','eafa0947-d859-57e8-b93e-affd8500f0a5'::uuid,'eoc_manager'::public.app_role,'anticipatory_action','draft',1,'protocol','SOP 4-03 (MOO Ch.4 v1.1); SOP GOV-05 when a State of Imminent Disaster is considered','CDRRMO Head; Research and Planning with Operations and Warning coordinate',array['RA 12287 and its IRR (2026)','NDRRMC-OCD Contingency Planning Guidebook (2020)']::text[],array['A8.6','A8.8','B1.2']::text[]),
('5efa3c12-b561-5c70-bfc4-5d6b1b17e8a7'::uuid,'PR-SOID-REQUEST','State of Imminent Disaster: request and declaration','Follow RA 12287, its IRR and SOP GOV-05 from the PDRA to the Mayor''s Executive Order.','When the PDRA classifies the projected impact as severe or its equivalent (including where IRR Rule II Sec. 4 factors support that classification below the thresholds) and there is enough lead time to carry out anticipatory action.','f66e432b-487f-5434-a8eb-de42ef848a67'::uuid,'eoc_manager'::public.app_role,'anticipatory_action','draft',1,'protocol','SOP GOV-05 (MOO Ch.1, Annex 1-E)','CDRRMO Head as CDRRMC secretariat',array['RA 12287 and its IRR (2026), Rules III and IV']::text[],array['A1.8','A4.6','A6.7']::text[]),
('f99e18a5-6514-56f9-8bf6-dc31df80cd6f'::uuid,'PR-SOC-DECLARE','State of Calamity: assessment, declaration and lifting','Follow RA 10121 Sec. 16 and SOP GOV-04: the Sangguniang Panlungsod declares or lifts, on the CDRRMC''s recommendation.','When damage and needs reports indicate that a State of Calamity may be warranted.','e715b34c-ec5f-5f4c-b34c-378225a2156c'::uuid,'cdrrmo_head'::public.app_role,'council','draft',1,'workflow','SOP GOV-04 (MOO Ch.1, Annex 1-D)','CDRRMO Head as CDRRMC secretariat',array['RA 10121 Sec. 16']::text[],array['A1.6']::text[]),
('7bcbdc7d-00f9-516a-a030-e4d89022be09'::uuid,'PR-FLASHFLOOD-EARLY','Flash flood and landslide early action','Act on short-lead hazards that cannot wait for a declaration.','When rainfall or river readings reach the City''s early-action thresholds for the Anilao–Malbasag system or upland barangays.','eafa0947-d859-57e8-b93e-affd8500f0a5'::uuid,'duty_officer'::public.app_role,'anticipatory_action','draft',1,'protocol','SOP 4-02 (MOO Ch.4 v1.1, short-lead hazards, sec. 6.3)','CDRRMO Operations and Warning (OpCen duty officer)',array['RA 10121 Sec. 12(c)','RA 12287 IRR (2026) Rule IV']::text[],array['A6.1','A6.2','A8.8']::text[]),
('90cb1850-de66-5a00-a46c-47db38ebdc84'::uuid,'PR-SITREP-CYCLE','SitRep cycle','Produce a verified SitRep on schedule every operational period.','At each scheduled SitRep time during an activation.','eafa0947-d859-57e8-b93e-affd8500f0a5'::uuid,'eoc_staff'::public.app_role,'reporting','draft',1,'protocol','SOP 4-08 (MOO Ch.4 v1.1)','EOC Planning / situation unit; approval by the official in the reporting route',array['DILG VIII Harmonized Disaster Response Reporting Template and SOP','NDRRMC Memo 131 s. 2018']::text[],array['B5.1','B5.2','B1.5','A10.3']::text[]),
('a37bb249-1b6f-585a-8b12-bc80b742cc63'::uuid,'PR-CDRRMC-MEETING','CDRRMC meeting (secretariat)','Run the Council meeting and keep its records complete.','Quarterly, and whenever the Chair calls a special meeting.','c906fb73-66a3-5477-8732-349b15f6e5c4'::uuid,'duty_officer'::public.app_role,'council','draft',1,'workflow','MOO Ch.1 (CDRRMC secretariat)','CDRRMO as CDRRMC secretariat',array['RA 10121 Sec. 11']::text[],array['A1.3','A1.4']::text[]),
('33dfaee2-77a8-5b13-956e-bb805634d0b1'::uuid,'PR-LIFT-REPORT','Lifting and 45-day report','Lift a State of Imminent Disaster correctly and report to OCD on time.','When the hazard occurs or the PDRA shows the projected impacts will not be met.','f66e432b-487f-5434-a8eb-de42ef848a67'::uuid,'eoc_manager'::public.app_role,'anticipatory_action','draft',1,'protocol','SOP GOV-05 (MOO Ch.1, Annex 1-E): lifting and the 45-day report','CDRRMO Head as CDRRMC secretariat',array['RA 12287 and its IRR (2026)']::text[],array['A10.8']::text[]),
('abcc88a5-8f0d-577d-84f7-eef04656abf0'::uuid,'WF-BUDGET-CYCLE','LDRRMF budget cycle (SOPs 5-01 and 5-02: computation to quarterly report)','Compute the LDRRMF on the correct base, plan it through an approved LDRRMFIP, execute it, and report and disclose its use every quarter (Chapter 5, SOPs 5-01 and 5-02).','Each budget call, a supplemental budget or realignment, and the end of every quarter.','d7190e43-31f8-55d7-b646-04574073dedf'::uuid,'cdrrmo_head'::public.app_role,'budget','draft',1,'workflow','SOP 5-01 and SOP 5-02 (MOO Ch.5 v1.0); formerly MOO Ch.2 sec. 2.16.2','CDRRMO Research and Planning (formulation, reporting); Administration and Training (execution); City Budget Office (computation)',array['RA 10121 Sec. 21','NDRRMC-DBM-DILG JMC 2013-1','RA 12287 IRR (2026) Rule V Sec. 1(b)','COA Circular No. 2012-002','DILG Full Disclosure Policy issuances']::text[],array['A3.5','A4.1','A4.2','A4.4','A4.6','A10.5','B7.5']::text[]),
('bf7c56c0-7c61-596a-bab4-0136aa67927d'::uuid,'WF-CP-ACTIVATION','Contingency plan activation and response clustering','Switch on the clusters and EOC modules the activated contingency plan needs, and stand them down when needs are met (Ch.1 sec. 6.3).','When the EOC goes to Blue or Red for a hazard covered by a contingency plan.','c906fb73-66a3-5477-8732-349b15f6e5c4'::uuid,'eoc_manager'::public.app_role,'response_clusters','draft',1,'workflow','MOO Ch.1 sec. 6.3','EOC Manager',array['NDRRMC Memo 131 s. 2018']::text[],array['A8.5','B1.4','B4.4']::text[]),
('41fad6bf-c424-5923-b011-9067cf54de64'::uuid,'WF-EOC-DESIGNATION','EOC designation review (quarterly)','Keep every key EOC position covered by a primary and two alternates (Annex 2-D; IAT B4.2).','Every quarter, and after any staff movement.','f379ea8e-ae82-5eb6-9887-f700227215ce'::uuid,'cdrrmo_head'::public.app_role,'workforce','draft',1,'workflow','SOP HR-06 (MOO Ch.2, Annex 2-L; register Annex 2-D)','CDRRMO Head / EOC Manager (SOP HR-06): EOC Manager proposes and maintains; CDRRMO Head approves',array['NDRRMC Memo 131 s. 2018','EOC Capability Assessment Checklist']::text[],array['B4.1','B4.2']::text[]),
('a277ed09-4908-5ad8-a47d-9d583ee2137d'::uuid,'WF-GEO-COP','Geospatial common operating picture (SOP 6-GIS-01)','Keep a consistent, validated map of incidents, affected areas, facilities and resources for the EOC.','Maintained in normal operations; run in full whenever the EOC is activated.','d47f0498-4189-5772-9e6c-fecd708e1cbc'::uuid,'eoc_staff'::public.app_role,'geospatial','draft',1,'workflow','SOP 6-GIS-01 (proposed EOC Module SOP; Library draft)','EOC Planning Section (GIS custodian)',array['NDRRMC Memo 131 s. 2018','RA 10173']::text[],array['A5.6','A5.7','B5.3']::text[]),
('4e10fa52-dda1-5ce8-b699-974ea48663df'::uuid,'WF-SOP3-01','SOP 3-1 Hazard data acquisition, validation and map release','Obtain authoritative, current and fit-for-purpose hazard information and control its use.','A request for risk information or a map; a new or revised product from a source agency.','77080547-c4e3-52f7-8908-02ce0fc78258'::uuid,'cdrrmo_head'::public.app_role,'risk_information','draft',1,'workflow','SOP 3-1 (MOO Ch.3 v1.0)','CDRRMO Research and Planning (GIS custodian)',array['RA 10121 Sec. 12(c)(3)','DHSUD MC 2025-004']::text[],array['A5.1','A5.6','C1.4']::text[]),
('49df9ce9-eaa5-5907-b3fa-a06882687788'::uuid,'WF-SOP3-02','SOP 3-2 Risk information and geospatial repository maintenance','Maintain a controlled, auditable City risk information base.','A new dataset; quarterly review; after a major event or a source-agency revision.','77080547-c4e3-52f7-8908-02ce0fc78258'::uuid,'cdrrmo_head'::public.app_role,'risk_information','draft',1,'workflow','SOP 3-2 (MOO Ch.3 v1.0)','CDRRMO Head (designated data custodian)',array['RA 10121 Sec. 12(c)(3) and (5)','RA 10173']::text[],array['A5.4','A5.5','A5.6','A5.7']::text[]),
('c624dc19-e6b9-51fe-bef6-d0ef90298714'::uuid,'WF-SOP3-03','SOP 3-3 City climate and disaster risk assessment','Produce a method-compliant CDRA that supports CLUP and development decisions.','CDRA update with the CLUP/CDP revision; material change in hazard, exposure or climate information; new DHSUD issuance.','77080547-c4e3-52f7-8908-02ce0fc78258'::uuid,'cdrrmo_head'::public.app_role,'risk_planning','draft',1,'workflow','SOP 3-3 (MOO Ch.3 v1.0)','CPDO (CDRA process) with the CDRRMO coordinating DRRM evidence',array['DHSUD MC 2025-004 (Enhanced CDRA)','RA 9729 as amended by RA 10174','RA 10121 Sec. 12(c)(3)']::text[],array['A5.2','A5.3','C1.1','C1.3']::text[]),
('90158e48-f867-57e2-a9da-980f5d20e634'::uuid,'WF-SOP3-04','SOP 3-4 Critical facilities and dependency/failure-chain analysis','Identify critical service dependencies and inform protection and restoration priorities.','Yearly; after a change to a critical asset; before a contingency plan or PSCP update.','77080547-c4e3-52f7-8908-02ce0fc78258'::uuid,'cdrrmo_head'::public.app_role,'risk_information','draft',1,'workflow','SOP 3-4 (MOO Ch.3 v1.0)','CDRRMO (coordination); asset owners accountable for asset data',array['RA 12287 IRR (2026) Rule I Sec. 5(b),(d)']::text[],array['A5.8']::text[]),
('c4aa5d23-496f-53b2-9a86-60a56971a06d'::uuid,'WF-SOP3-05','SOP 3-5 LDRRMP and DRR/CCA mainstreaming interface','Ensure risk evidence is converted into plans, programmes and budget decisions.','Yearly planning and budget cycle (AIP, LDRRMFIP); LDRRMP review; each investment proposal.','77080547-c4e3-52f7-8908-02ce0fc78258'::uuid,'cdrrmo_head'::public.app_role,'risk_planning','draft',1,'workflow','SOP 3-5 (MOO Ch.3 v1.0)','CDRRMO (LDRRMP); CPDO (development-plan integration)',array['RA 10121 Sec. 2 and 12(c)(6)','RA 7160','RA 9729 as amended by RA 10174','NDRRMC-DBM-DILG JMC 2013-1']::text[],array['A3.1','A3.2','C1.1','C1.2','C1.4']::text[]),
('bf9ab417-2698-5c21-9201-36856ff49f99'::uuid,'WF-SOP3-06','SOP 3-6 Hazard-specific contingency plan development and control','Prepare and maintain tested plans for priority hazard scenarios.','A priority hazard without a current plan; a plan past its validity; after an exercise or event; yearly review.','77080547-c4e3-52f7-8908-02ce0fc78258'::uuid,'cdrrmo_head'::public.app_role,'contingency_planning','draft',1,'workflow','SOP 3-6 (MOO Ch.3 v1.0)','CDRRMO (coordinating process owner); hazard and sector leads (technical owners)',array['RA 10121 Sec. 12(c)','NDRRMC-OCD Contingency Planning Guidebook (2020)']::text[],array['A3.3','A3.6']::text[]),
('7ff2c261-e05f-5d3a-9699-ff0b584a84c1'::uuid,'WF-SOP3-07','SOP 3-7 Public service continuity planning','Protect essential City functions during disruption.','Mayor''s directive; yearly review; after a disruption or exercise.','77080547-c4e3-52f7-8908-02ce0fc78258'::uuid,'cdrrmo_head'::public.app_role,'continuity','draft',1,'workflow','SOP 3-7 (MOO Ch.3 v1.0)','City continuity executive (to be designated); department heads for their services',array['NDRRMC-OCD PSCP Guidebook']::text[],array['A3.4','B2.7']::text[]),
('3d22ea60-9da2-50c2-889c-f70876393abf'::uuid,'WF-SOP3-08','SOP 3-8 Barangay DRRM plan review and quality assurance','Maintain a verified, quality-assured city-wide BDRRMP status for the 85 barangays.','Yearly BDRRMP cycle; DILG call for plans; a new plan period.','77080547-c4e3-52f7-8908-02ce0fc78258'::uuid,'cdrrmo_head'::public.app_role,'risk_planning','draft',1,'workflow','SOP 3-8 (MOO Ch.3 v1.0)','BDRRMC/Barangay Development Council (plan owner); CDRRMO (city reviewer)',array['RA 10121 Sec. 12(c)(6)','DILG MC 2025-035 (Listo si KAP)']::text[],array['A3.7']::text[]),
('df644c53-097f-508d-a224-5f5f3277a454'::uuid,'WF-SOP3-09','SOP 3-9 Inclusive risk assessment and ecosystem monitoring interface','Embed inclusion and protective-ecosystem evidence in risk intelligence and preparedness.','Each CDRA or plan update; yearly monitoring.','77080547-c4e3-52f7-8908-02ce0fc78258'::uuid,'cdrrmo_head'::public.app_role,'risk_information','draft',1,'workflow','SOP 3-9 (MOO Ch.3 v1.0)','CDRRMO (coordination); sector offices and CENRO/DENR (technical owners)',array['RA 9710','RA 7277 as amended','RA 10821','RA 8371','RA 10173','RA 9729 as amended by RA 10174']::text[],array['A5.3','A5.5','A7.6','C3.1','C3.2']::text[]),
('6e6abacf-798b-5262-971a-6b8852c22dcc'::uuid,'PR-WARNING-RECEIPT','SOP 4-01 Official warning receipt, verification and escalation','Authenticate, time-stamp and interpret each official product within its source limits, and escalate it to the right decision-maker.','On receipt of an official warning product or a significant local report.','eafa0947-d859-57e8-b93e-affd8500f0a5'::uuid,'duty_officer'::public.app_role,'warning','draft',1,'protocol','SOP 4-01 (MOO Ch.4 v1.1)','CDRRMO Operations and Warning (OpCen duty officer); escalation to the CDRRMO Head',array['RA 10121 Sec. 12(c)','DILG VIII Disaster Response Reporting SOP (RDRRMC8 Res. 12-006)']::text[],array['A6.1','B4.3']::text[]),
('1d2564de-8992-55c2-94a7-5c14a0a0f1e4'::uuid,'PR-ICS-INTERFACE','SOP 4-05 Initial incident coordination and EOC–ICS interface','Build a shared operational picture and support the Incident Commander without duplicating field command.','On notification of an incident that needs EOC coordination.','eafa0947-d859-57e8-b93e-affd8500f0a5'::uuid,'eoc_manager'::public.app_role,'eoc','draft',1,'protocol','SOP 4-05 (MOO Ch.4 v1.1)','EOC Manager; the Incident Commander / IMT keeps field command',array['NDRRMC Memo 131 s. 2018','NDRRMC MC No. 4 s. 2012 (ICS)']::text[],array['A8.1','B6.1','B1.4','B1.5']::text[]),
('0edbd70e-0dfb-5863-83a8-dab3be25d250'::uuid,'PR-EVACUATION','SOP 4-06 Evacuation coordination and monitoring','Coordinate an authorised evacuation and monitor it safely, accessibly and accountably. The MOO creates no power to order evacuation.','When an official warning, PDRA or incident report indicates people may need to move.','eafa0947-d859-57e8-b93e-affd8500f0a5'::uuid,'eoc_manager'::public.app_role,'eoc','draft',1,'protocol','SOP 4-06 (MOO Ch.4 v1.1)','Decision: official or body named by law and City issuance; CDRRMO coordinates; CSWDO leads camp management (JMC No. 2 s. 2021)',array['RA 10121 Sec. 12(c)','RA 12076','RA 10821','DSWD-DILG-DOH-DepEd JMC No. 2 s. 2021 (CCCM)']::text[],array['A6.2','A7.4','A7.6','A7.9']::text[]),
('cb839857-6ab2-5c3c-9680-1cb7dcbfd1ed'::uuid,'PR-RESOURCE-REQUEST','SOP 4-07 Resource request coordination and mutual-aid escalation','Move each operational request from receipt to fulfilment or referral, with financial and property controls.','On receipt of a resource or service request during an activation.','eafa0947-d859-57e8-b93e-affd8500f0a5'::uuid,'eoc_manager'::public.app_role,'eoc','draft',1,'protocol','SOP 4-07 (MOO Ch.4 v1.1)','EOC Manager / Logistics; approval and expenditure stay with the competent offices (Chapter 5)',array['RA 10121 Sec. 21','RA 12009 and its IRR']::text[],array['B6.2','A8.3','A7.5']::text[]),
('94f696d5-6a2a-5381-8b5a-afbfc787e786'::uuid,'PR-EOC-DEACTIVATE','SOP 4-09 EOC deactivation, transition and after-action review','Close the activation in a controlled way and hand unresolved work to permanent, recovery and continuity arrangements.','When the incident has stabilised and the Incident Commander recommends termination.','eafa0947-d859-57e8-b93e-affd8500f0a5'::uuid,'eoc_manager'::public.app_role,'eoc','draft',1,'protocol','SOP 4-09 (MOO Ch.4 v1.1)','Deactivation: official designated in the EOC EO; EOC Manager coordinates handover and closeout',array['NDRRMC Memo 131 s. 2018','NDRRMC-OCD Contingency Planning Guidebook (2020)','NEDA Disaster Rehabilitation and Recovery Planning Guide']::text[],array['B1.3','B7.4','A10.6']::text[]),
('07f102ff-c1d0-5203-924f-6bdcca90726d'::uuid,'WF-SOP5-03','SOP 5-03 Special Trust Fund ledger, ageing and programming','Use every unexpended LDRRMF balance for DRRM within its five-year period, oldest first.','Year-end closing; LDRRMFIP preparation; any STF reallocation request.','d7190e43-31f8-55d7-b646-04574073dedf'::uuid,'cdrrmo_head'::public.app_role,'budget','draft',1,'workflow','SOP 5-03 (MOO Ch.5 v1.0)','City Accountant (ledger); CDRRMO Research and Planning (programming)',array['RA 10121 Sec. 21','COA Circular No. 2012-002','RA 12287 IRR (2026) Rule V Secs. 1(b) and 3']::text[],array['A4.3','A4.6']::text[]),
('b653cdf1-b886-5c46-bb92-39bd6d122d66'::uuid,'PR-QRF-USE','SOP 5-04 Quick Response Fund use under a State of Calamity','Release the QRF quickly, only for relief and recovery, and only under a State of Calamity declared by the SP.','SP declaration of a State of Calamity covering the City or affected barangays.','d7190e43-31f8-55d7-b646-04574073dedf'::uuid,'cdrrmo_head'::public.app_role,'eoc','draft',1,'protocol','SOP 5-04 (MOO Ch.5 v1.0)','CDRRMO Head; EOC Finance/Administration desk. Declaration: SP (SOP GOV-04). Expenditure: City Mayor within the appropriation',array['RA 10121 Secs. 16 and 21','NDRRMC-DBM-DILG JMC 2013-1','COA Circular No. 2012-002']::text[],array['A4.2','A1.6']::text[]),
('4f52ff98-ce0a-56a6-a7e1-1c2effedca46'::uuid,'PR-AA-FUNDS','SOP 5-05 Anticipatory action funding and disbursement under a State of Imminent Disaster','Release AA funds immediately and lawfully once a State of Imminent Disaster is declared, within the 10% ceiling and the tranche rule.','The Mayor''s declaration of a State of Imminent Disaster; a revised impact forecast during the declaration.','d7190e43-31f8-55d7-b646-04574073dedf'::uuid,'cdrrmo_head'::public.app_role,'anticipatory_action','draft',1,'protocol','SOP 5-05 (MOO Ch.5 v1.0)','CDRRMO Head; EOC Finance/Administration desk. Declaration: City Mayor (SOP GOV-05). Certification and release: Budget, Accounting, Treasury',array['RA 12287 Secs. 6-7','RA 12287 IRR (2026) Rules IV-VI','RA 12009 Sec. 35(b)']::text[],array['A4.6','A10.8','B6.6']::text[]),
('233233d0-5320-5050-bbae-e7069048869e'::uuid,'WF-SOP5-06','SOP 5-06 Pre-arranged supply: supplier list, framework agreements and specifications','Make emergency and AA purchases fast and lawful by agreeing suppliers, items and prices before the event.','Each year before the typhoon season; after an event that exposed a supply gap.','d7190e43-31f8-55d7-b646-04574073dedf'::uuid,'cdrrmo_head'::public.app_role,'budget','draft',1,'workflow','SOP 5-06 (MOO Ch.5 v1.0)','CDRRMO Administration and Training with CGSO and the BAC Secretariat; award by the HoPE',array['RA 12009 Secs. 16 and 35(b) and IRR','RA 12287 IRR (2026) Rule IV']::text[],array['A4.5','B6.6','B6.3']::text[]),
('ad223db4-da40-5c63-85cc-42ad2f6463d3'::uuid,'PR-EMERGENCY-PROCURE','SOP 5-07 Emergency procurement (negotiated procurement - emergency cases)','Buy what an emergency requires, quickly, with its legal ground on record before the purchase.','An urgent need during a State of Calamity, or where time is of the essence because of a calamity.','d7190e43-31f8-55d7-b646-04574073dedf'::uuid,'eoc_manager'::public.app_role,'eoc','draft',1,'protocol','SOP 5-07 (MOO Ch.5 v1.0)','EOC Finance/Administration desk and the requesting office; award by the HoPE on BAC recommendation',array['RA 12009 Sec. 35(b) and IRR']::text[],array['A4.5']::text[]),
('67421122-54ae-5d9f-97f3-6eaa6c1652d7'::uuid,'WF-SOP5-08','SOP 5-08 Donations and external assistance: receipt, recording, custody, use and disclosure','Receive donations transparently and use them as the donor and the law intend.','An offer or delivery of cash or in-kind assistance.','d7190e43-31f8-55d7-b646-04574073dedf'::uuid,'cdrrmo_head'::public.app_role,'budget','draft',1,'workflow','SOP 5-08 (MOO Ch.5 v1.0)','CSWDO (relief goods), CGSO (property), City Treasurer (cash); acceptance by the City Mayor (SP Res. 2024-102); CDRRMO coordinates',array['SP Res. 2024-102','COA Circular No. 2012-002','RA 12287 IRR (2026) Rule V Sec. 2','RA 10173']::text[],array['B6.4']::text[]),
('8779a83c-c39d-5829-8f4f-77ee65426a1f'::uuid,'WF-SOP5-09','SOP 5-09 Fund adequacy test and risk financing','Know how far City funds cover a severe credible event, and close the gap with insurance and pre-arranged sources.','Each year before the LDRRMFIP; after a major event or a CDRA update.','d7190e43-31f8-55d7-b646-04574073dedf'::uuid,'cdrrmo_head'::public.app_role,'budget','draft',1,'workflow','SOP 5-09 (MOO Ch.5 v1.0)','CDRRMO Research and Planning with the City Budget Office, CGSO and CPDO',array['RA 10121 Sec. 21','RA 656','RA 9729 as amended by RA 10174','UNDRR Disaster Resilience Scorecard 3.2.3-3.2.4']::text[],array['A4.9','A4.7','A9.5']::text[]),
('a6f9ffbc-06b0-50f5-9b7c-e7d54d8e2986'::uuid,'WF-SOP5-10','SOP 5-10 Audit readiness, COA observations and internal control','Prevent common findings and close COA observations on DRRM funds.','Before year-end (pre-audit check); receipt of an AOM or the Annual Audit Report.','d7190e43-31f8-55d7-b646-04574073dedf'::uuid,'cdrrmo_head'::public.app_role,'budget','draft',1,'workflow','SOP 5-10 (MOO Ch.5 v1.0)','CDRRMO Administration and Training with the City Accountant and the Internal Audit Service where constituted; the City Mayor replies to COA',array['COA Circular No. 2012-002']::text[],array['A4.8']::text[])
